-- Apache Derby - Gryffindor
-- Crea la tabla ALUMNOS y carga los 303 registros.
-- Columnas excluidas: alias, patronus_origen, wiki.
-- NACIMIENTO es DATE y las fechas imprecisas se han estimado.

CREATE TABLE alumnos (
    id VARCHAR(36) PRIMARY KEY,
    nombre VARCHAR(150) NOT NULL,
    casa VARCHAR(50) NOT NULL,
    especie VARCHAR(100),
    genero VARCHAR(50),
    nacimiento DATE NOT NULL,
    nacionalidad VARCHAR(150),
    patronus VARCHAR(150),
    imagen VARCHAR(1000)
);


COMMIT;
